// Independent scratch oracle: regular ADM curvature vs conformal transformation,
// and conformally transformed exact Minkowski dipole vs continuous wave equations.
#define main ExportWaveMain
#include "export_wave.cpp"
#undef main
struct ExactPoint {double phi,pi,phit,pit;};
void Profile(double s,double *f){double z=(s+.5)/.35,F=.001*std::exp(-z*z);f[0]=F;f[1]=-2*z*F/.35;f[2]=(4*z*z-2)*F/(.35*.35);f[3]=(12*z-8*z*z*z)*F/std::pow(.35,3);}
double RetardedIntegral(const hyp::LayerReference<double>&ref,double r,int panels){double sum=1/ref.At(0,0,0).outgoing+1/ref.At(r,0,0).outgoing;for(int j=1;j<panels;++j)sum+=(j%2?4:2)/ref.At(r*j/panels,0,0).outgoing;return sum*r/(3*panels);}
ExactPoint Exact(const hyp::LayerReference<double>&ref,const double*x,double t,int panels){auto p=ref.At(x[0],x[1],x[2]);double r=p.radius,om=p.omega,u=t-RetardedIntegral(ref,r,panels),v=u+2*r/om;double f[4],g[4];Profile(u,f);Profile(v,g);double op=0,br=0,angle=(.3*x[0]+.4*x[1]+std::sqrt(.75)*x[2])/r;for(int d=0;d<3;++d){op+=x[d]*p.domega[d]/r;br+=x[d]*p.beta[d]/r;}double du=-1/p.outgoing,dv=du+2*p.L/(om*om),B=f[0]-g[0],S=f[1]+g[1];double val=-S/r-om*B/(r*r),dt=-(f[2]+g[2])/r-om*(f[1]-g[1])/(r*r),dr=-(f[2]*du+g[2]*dv)/r+S/(r*r)-op*B/(r*r)-om*(f[1]*du-g[1]*dv)/(r*r)+2*om*B/(r*r*r),dtt=-(f[3]+g[3])/r-om*(f[2]-g[2])/(r*r),drdt=-(f[3]*du+g[3]*dv)/r+(f[2]+g[2])/(r*r)-op*(f[1]-g[1])/(r*r)-om*(f[2]*du-g[2]*dv)/(r*r)+2*om*(f[1]-g[1])/(r*r*r);return {angle*val,angle*(dt-br*dr)/p.alpha,angle*dt,angle*(dtt-br*drdt)/p.alpha};}
int main(int argc,char**argv){Kokkos::ScopeGuard guard(argc,argv);hyp::LayerReference<double>ref(1,.5,{true,.05,.95});double kerr=0,rerr=0,transformerr=0,Rmin=1e99,Rmax=-1e99,inmin=1e99;for(int j=0;j<=2048;++j){double r=double(j)/2048,x=.3*r,y=.4*r,z=std::sqrt(.75)*r;auto c=Coefficients(ref,x,y,z,kerr,rerr);Rmin=std::min(Rmin,c.R);Rmax=std::max(Rmax,c.R);inmin=std::min(inmin,std::abs(c.ingoing));if(c.omega<.1)continue;const auto p=ref.At(x,y,z);const auto&m=p.state;auto metric=hyp::PenroseMetric(m.metric,m.chi);auto geo=hyp::Geometry(metric);hyp::OmegaJet<double>o{};o.omega=p.omega;for(int d=0;d<3;++d){o.gradient[d]=p.domega[d];for(int e=0;e<3;++e)o.hessian[d][e]=p.omega_hessian[d][e];}hyp::SetStationaryOmegaNormal(m.alpha.value,m.beta.value,m.alpha.d,m.beta.d,o);double lap=0,norm=-o.normal*o.normal,box=c.K*o.normal;for(int d=0;d<3;++d){box+=c.beta[d]*o.dnormal[d]/c.alpha;for(int e=0;e<3;++e){norm+=c.inv[d][e]*o.gradient[d]*o.gradient[e];box+=c.inv[d][e]*m.alpha.d[d]*o.gradient[e]/c.alpha;double H=o.hessian[d][e];for(int a=0;a<3;++a)H-=geo.connection[a][d][e]*o.gradient[a];lap+=c.inv[d][e]*H;}}box+=lap;transformerr=std::max(transformerr,std::abs(c.R-(12*norm/(o.omega*o.omega)-6*box/o.omega)));}
 std::cout<<std::setprecision(17)<<"{\"stationary_K_error\":"<<kerr<<",\"pure_CMC_R_error\":"<<rerr<<",\"conformal_transform_R_error_Omega_ge_.1\":"<<transformerr<<",\"dense_R_min\":"<<Rmin<<",\"dense_R_max\":"<<Rmax<<",\"scri_incoming\":"<<inmin<<",\"continuous_exact_dipole_FD_oracle\":[";
 bool comma=false;for(double h:{.0004,.0002,.0001}){double errphi=0,errpi=0;for(double r:{.08,.18,.35,.5,.65,.8,.92,.975})for(double t:{0.,.2}){double x[3]={.3*r,.4*r,std::sqrt(.75)*r};auto c=Coefficients(ref,x[0],x[1],x[2],kerr,rerr);auto e=Exact(ref,x,t,1024);double grad[3]{},gradpi[3]{},hess[3][3]{};for(int d=0;d<3;++d){double xp[3]={x[0],x[1],x[2]},xm[3]={x[0],x[1],x[2]},xpp[3]={x[0],x[1],x[2]},xmm[3]={x[0],x[1],x[2]};xp[d]+=h;xm[d]-=h;xpp[d]+=2*h;xmm[d]-=2*h;auto ep=Exact(ref,xp,t,1024),em=Exact(ref,xm,t,1024),epp=Exact(ref,xpp,t,1024),emm=Exact(ref,xmm,t,1024);grad[d]=(emm.phi-8*em.phi+8*ep.phi-epp.phi)/(12*h);gradpi[d]=(emm.pi-8*em.pi+8*ep.pi-epp.pi)/(12*h);hess[d][d]=(-epp.phi+16*ep.phi-30*e.phi+16*em.phi-emm.phi)/(12*h*h);for(int a=d+1;a<3;++a){const double weights[4]={1,-8,8,-1};const int offsets[4]={-2,-1,1,2};for(int j=0;j<4;++j)for(int k=0;k<4;++k){double xx[3]={x[0],x[1],x[2]};xx[d]+=offsets[j]*h;xx[a]+=offsets[k]*h;hess[d][a]+=weights[j]*weights[k]*Exact(ref,xx,t,1024).phi/(144*h*h);}hess[a][d]=hess[d][a];}}
 double rhsphi=c.alpha*e.pi,rhspi=c.alpha*c.K*e.pi-c.alpha*c.R*e.phi/6;for(int d=0;d<3;++d){rhsphi+=c.beta[d]*grad[d];rhspi+=c.beta[d]*gradpi[d]+c.first[d]*grad[d];for(int a=0;a<3;++a)rhspi+=c.alpha*c.inv[d][a]*hess[d][a];}errphi=std::max(errphi,std::abs(rhsphi-e.phit));errpi=std::max(errpi,std::abs(rhspi-e.pit));}if(comma)std::cout<<',';comma=true;std::cout<<"{\"h\":"<<h<<",\"phi_rhs_max_error\":"<<errphi<<",\"pi_rhs_max_error\":"<<errpi<<"}";}std::cout<<"]}\n";
}
